import { BookPreviewIconButton } from './book-preview-icon-button'
import { BookPreviewModePicker } from './book-preview-mode-picker'
import { useBookPreview } from './book-preview-provider'
import { useCoarsePointer, useNarrowLayout } from './media'
import type { BookPreviewAppearance } from './types'

const appearances: { value: BookPreviewAppearance; label: string }[] = [
  { value: 'system', label: 'System' },
  { value: 'sepia', label: 'Sepia' },
  { value: 'light', label: 'Light' },
  { value: 'dark', label: 'Dark' },
  { value: 'oled', label: 'OLED' },
]

export function BookPreviewToolbar() {
  const {
    state,
    source,
    setAppearance,
    setSound,
    toggleFullscreen,
    fullscreen,
    goToPage,
    uploadPdf,
    setChromeHost,
  } = useBookPreview()
  const narrow = useNarrowLayout()
  const coarse = useCoarsePointer()
  const appearanceLabel =
    appearances.find((item) => item.value === state.appearance)?.label ??
    'Paper'
  // A document-provided outline (PDF bookmarks) wins over titles synthesized
  // from page data — it is the author's own table of contents.
  const contents =
    state.contents.length > 0
      ? state.contents.map((entry) => ({
          title: entry.title,
          index: entry.pageIndex,
          depth: entry.depth,
        }))
      : source.pages
          .map((page, index) => ({
            title: page.title ?? page.kicker,
            index,
            depth: 0,
          }))
          .filter(
            (entry): entry is { title: string; index: number; depth: number } =>
              Boolean(entry.title),
          )

  return (
    <div
      data-book-preview-surface
      data-book-preview-chrome
      className="bg-card flex min-w-0 flex-wrap items-center justify-between gap-2 rounded-xl border p-2 sm:gap-3 sm:p-3"
    >
      <BookPreviewModePicker />
      {/* Engines portal their controls into this slot — the reader keeps a
          single chrome bar instead of a second row floating above the stage. */}
      <div ref={setChromeHost} className="contents" />
      <div className="flex flex-wrap items-center gap-2">
        {state.capabilities.appearance ? (
          <AppearanceControl
            appearance={state.appearance}
            appearanceLabel={appearanceLabel}
            compact={narrow || coarse}
            onSelect={setAppearance}
          />
        ) : null}
        <Separator orientation="vertical" className="hidden h-6 sm:block" />
        {contents.length > 1 ? (
          <ContentsMenu contents={contents} goToPage={goToPage} />
        ) : null}
        <ToolbarActions
          soundCapable={state.capabilities.sound}
          sound={state.sound}
          fullscreenCapable={state.capabilities.fullscreen}
          fullscreen={fullscreen}
          downloadCapable={state.capabilities.download}
          downloadUrl={source.downloadUrl}
          downloadFileName={source.downloadFileName}
          uploadCapable={source.allowPdfUpload}
          onUploadPdf={uploadPdf}
          onSetSound={setSound}
          onToggleFullscreen={toggleFullscreen}
        />
      </div>
    </div>
  )
}

function AppearanceControl({
  appearance,
  appearanceLabel,
  compact,
  onSelect,
}: {
  appearance: BookPreviewAppearance
  appearanceLabel: string
  compact: boolean
  onSelect: (value: BookPreviewAppearance) => void
}) {
  if (compact) {
    return (
      <DropdownMenu>
        <DropdownMenuTrigger
          render={
            <Button
              type="button"
              variant="outline"
              size="sm"
              aria-label="Paper appearance"
              data-book-preview-press
            />
          }
        >
          {appearanceLabel}
          <IconChevronDown data-icon="inline-end" />
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end">
          <DropdownMenuGroup>
            {appearances.map((item) => (
              <DropdownMenuItem
                key={item.value}
                onClick={() => onSelect(item.value)}
              >
                {item.label}
              </DropdownMenuItem>
            ))}
          </DropdownMenuGroup>
        </DropdownMenuContent>
      </DropdownMenu>
    )
  }

  return (
    <ToggleGroup
      value={[appearance]}
      onValueChange={(value) => {
        if (value[0]) onSelect(value[0] as BookPreviewAppearance)
      }}
      variant="outline"
      size="sm"
      spacing={0}
      aria-label="Paper appearance"
    >
      {appearances.map((item) => (
        <ToggleGroupItem
          key={item.value}
          value={item.value}
          aria-label={item.label}
        >
          {item.label}
        </ToggleGroupItem>
      ))}
    </ToggleGroup>
  )
}

function ToolbarActions({
  soundCapable,
  sound,
  fullscreenCapable,
  fullscreen,
  downloadCapable,
  downloadUrl,
  downloadFileName,
  uploadCapable,
  onUploadPdf,
  onSetSound,
  onToggleFullscreen,
}: {
  soundCapable: boolean
  sound: boolean
  fullscreenCapable: boolean
  fullscreen: boolean
  downloadCapable: boolean
  downloadUrl?: string
  downloadFileName?: string
  uploadCapable: boolean
  onUploadPdf: (file: File) => void
  onSetSound: (sound: boolean) => void
  onToggleFullscreen: () => void
}) {
  const uploadInputRef = useRef<HTMLInputElement | null>(null)

  return (
    <>
      {uploadCapable ? (
        <>
          <input
            ref={uploadInputRef}
            type="file"
            accept="application/pdf,.pdf"
            className="sr-only"
            tabIndex={-1}
            aria-hidden
            onChange={(event) => {
              const file = event.target.files?.[0]
              event.target.value = ''
              if (file) onUploadPdf(file)
            }}
          />
          <BookPreviewIconButton
            label="Open a PDF"
            onClick={() => uploadInputRef.current?.click()}
          >
            <IconUpload />
          </BookPreviewIconButton>
        </>
      ) : null}
      {soundCapable ? (
        <BookPreviewIconButton
          label={sound ? 'Mute page sounds' : 'Enable page sounds'}
          pressed={sound}
          onClick={() => onSetSound(!sound)}
        >
          {sound ? <IconVolume /> : <IconVolumeOff />}
        </BookPreviewIconButton>
      ) : null}
      {fullscreenCapable ? (
        <BookPreviewIconButton
          label={fullscreen ? 'Exit fullscreen' : 'Enter fullscreen'}
          pressed={fullscreen}
          onClick={onToggleFullscreen}
        >
          {fullscreen ? <IconMinimize /> : <IconMaximize />}
        </BookPreviewIconButton>
      ) : null}
      {downloadCapable && downloadUrl ? (
        <Button
          render={
            <a
              href={downloadUrl}
              download={downloadFileName}
              aria-label="Download document"
            />
          }
          nativeButton={false}
          variant="ghost"
          size="icon-sm"
          data-book-preview-press
        >
          <IconDownload />
          <span className="sr-only">Download document</span>
        </Button>
      ) : null}
    </>
  )
}

function ContentsMenu({
  contents,
  goToPage,
}: {
  contents: { title: string; index: number; depth: number }[]
  goToPage: (index: number) => void
}) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            type="button"
            variant="ghost"
            size="icon-sm"
            aria-label="Contents"
            data-book-preview-press
            className="min-h-11 min-w-11 sm:min-h-7 sm:min-w-7"
          />
        }
      >
        <IconList />
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="max-h-80">
        <DropdownMenuGroup>
          {contents.map((entry, position) => (
            <DropdownMenuItem
              key={`${entry.index}-${position}`}
              onClick={() => goToPage(entry.index)}
              className="justify-between gap-4"
            >
              <span
                className="truncate"
                style={{ paddingLeft: `${Math.min(entry.depth, 4) * 0.75}rem` }}
              >
                {entry.title}
              </span>
              <span className="text-muted-foreground font-mono text-xs">
                {entry.index + 1}
              </span>
            </DropdownMenuItem>
          ))}
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

'use client'

import type { ReactNode } from 'react'
import { cn } from '@/lib/utils'
import { BookPreviewStatus } from './book-preview-status'
import { useBookPreview } from './book-preview-provider'

export function BookPreviewViewport({ children }: { children?: ReactNode }) {
  const { state, retry, setMode, enabledEngines } = useBookPreview()
  const pageEngine = enabledEngines.find((engine) => engine.id === 'page')
  const blocking =
    state.status === 'loading' ||
    state.status === 'idle' ||
    state.status === 'empty' ||
    state.status === 'unsupported' ||
    state.status === 'error'

  return (
    <div
      className="bg-card relative isolate min-h-[min(30rem,80svh)] w-full min-w-0 overflow-hidden rounded-xl border sm:min-h-[min(32rem,74svh)] lg:min-h-[min(40rem,80svh)] xl:min-h-[min(48rem,84svh)]"
      data-book-preview-surface
      data-book-preview-viewport
    >
      {!blocking && state.totalPages > 1 ? (
        <div
          className="bg-foreground/10 absolute inset-x-0 top-0 z-20 h-0.5 overflow-hidden rounded-t-xl"
          aria-hidden
          data-book-preview-progress
        >
          {/* scaleX rather than width: width animates on the layout path
              every single page turn, transform stays on the compositor. */}
          <div
            className="bg-foreground/50 h-full w-full origin-left transition-transform duration-300 ease-out motion-reduce:transition-none"
            style={{
              transform: `scaleX(${Math.min(1, Math.max(0, state.pageIndex / Math.max(state.totalPages - 1, 1)))})`,
            }}
          />
        </div>
      ) : null}
      {blocking ? (
        <div className="absolute inset-0 z-10">
          <BookPreviewStatus
            status={state.status}
            error={state.error}
            onRetry={retry}
            onReload={
              state.error?.kind === 'engine-load'
                ? () => window.location.reload()
                : undefined
            }
            onFallback={
              pageEngine && state.mode !== 'page'
                ? () => setMode('page')
                : undefined
            }
          />
        </div>
      ) : null}
      <div
        data-book-preview-fade
        className={cn(
          'absolute inset-0',
          blocking && 'pointer-events-none opacity-0',
        )}
        aria-hidden={blocking}
        inert={blocking}
      >
        {children}
      </div>
    </div>
  )
}

'use client'

import { useId, useState } from 'react'
import { IconChevronLeft, IconChevronRight } from '@tabler/icons-react'
import { Button } from '@/components/ui/button'
import { Slider } from '@/components/ui/slider'
import { useBookPreview } from './book-preview-provider'

export function BookPreviewNavigation() {
  const { state, canGoPrev, canGoNext, prevPage, nextPage, goToPage } =
    useBookPreview()
  const total = Math.max(state.totalPages, 1)
  const [scrub, setScrub] = useState<number | null>(null)
  const [jumpDraft, setJumpDraft] = useState<string | null>(null)
  const jumpId = useId()
  const shown = scrub ?? state.pageIndex

  const commitJump = (raw: string) => {
    const next = Number.parseInt(raw, 10)
    if (Number.isFinite(next)) goToPage(next - 1)
    setJumpDraft(null)
  }

  // A non-paginated engine (the 3D book counts spreads, not pages) would show
  // a counter and slider whose numbers mean nothing — keyboard navigation
  // still drives it through the shell.
  if (state.capabilities.pagination === false) return null

  return (
    <div className="flex w-full flex-col gap-3" data-book-preview-chrome>
      <div className="flex items-center justify-between gap-3">
        <Button
          type="button"
          variant="ghost"
          size="sm"
          onClick={prevPage}
          disabled={!canGoPrev}
          aria-label="Previous page"
          data-book-preview-press
          className="min-h-11 min-w-11"
        >
          <IconChevronLeft data-icon="inline-start" />
          Previous
        </Button>
        {state.totalPages === 0 ? (
          <p className="text-muted-foreground font-mono text-xs">No pages</p>
        ) : (
          <form
            className="text-muted-foreground flex items-baseline gap-1.5 font-mono text-xs"
            aria-live={scrub === null ? 'polite' : 'off'}
            onSubmit={(event) => {
              event.preventDefault()
              commitJump(jumpDraft ?? '')
            }}
          >
            <label htmlFor={jumpId}>Page</label>
            <input
              id={jumpId}
              name="page"
              value={jumpDraft ?? String(shown + 1)}
              inputMode="numeric"
              className="focus-visible:bg-muted focus-visible:ring-ring/50 max-w-[6ch] min-w-[3ch] rounded bg-transparent text-center outline-none focus-visible:ring-1"
              size={Math.max(String(shown + 1).length + 1, 3)}
              onFocus={(event) => {
                setJumpDraft(String(shown + 1))
                event.target.select()
              }}
              onChange={(event) => {
                setJumpDraft(event.target.value.replace(/[^0-9]/g, ''))
              }}
              onBlur={() => commitJump(jumpDraft ?? '')}
              onKeyDown={(event) => {
                if (event.key === 'Escape') {
                  setJumpDraft(null)
                  event.currentTarget.blur()
                }
              }}
            />
            <span aria-hidden>of {state.totalPages}</span>
            <span className="sr-only">
              Page {shown + 1} of {state.totalPages}
            </span>
          </form>
        )}
        <Button
          type="button"
          variant="ghost"
          size="sm"
          onClick={nextPage}
          disabled={!canGoNext}
          aria-label="Next page"
          data-book-preview-press
          className="min-h-11 min-w-11"
        >
          Next
          <IconChevronRight data-icon="inline-end" />
        </Button>
      </div>
      {state.totalPages > 1 ? (
        <Slider
          value={shown}
          min={0}
          max={total - 1}
          step={1}
          aria-label="Page position"
          onValueChange={(value) =>
            setScrub(Array.isArray(value) ? value[0] : value)
          }
          onValueCommitted={(value) => {
            const next = Array.isArray(value) ? value[0] : value
            setScrub(null)
            if (typeof next === 'number') goToPage(next, 'instant')
          }}
        />
      ) : null}
    </div>
  )
}

'use client'

import { useState } from 'react'
import { IconChevronDown } from '@tabler/icons-react'
import { Button } from '@/components/ui/button'
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from '@/components/ui/sheet'
import { ToggleGroup, ToggleGroupItem } from '@/components/ui/toggle-group'
import { useBookPreview } from './book-preview-provider'
import type { BookPreviewMode } from './types'

export function BookPreviewModePicker() {
  const { enabledEngines, state, setMode, prefetchMode, finePointer } =
    useBookPreview()
  const [sheetOpen, setSheetOpen] = useState(false)

  if (enabledEngines.length <= 1) return null

  const currentLabel =
    enabledEngines.find((engine) => engine.id === state.mode)?.label ?? 'Mode'

  return (
    <>
      <div className="hidden [@media(pointer:coarse)]:contents">
        <Button
          type="button"
          variant="outline"
          size="sm"
          className="min-h-11 sm:min-h-8"
          onClick={() => setSheetOpen(true)}
          data-book-preview-press
        >
          {currentLabel}
          <IconChevronDown data-icon="inline-end" />
        </Button>
        <Sheet open={sheetOpen} onOpenChange={setSheetOpen}>
          <SheetContent side="bottom" className="gap-4">
            <SheetHeader>
              <SheetTitle>Choose a reader</SheetTitle>
              <SheetDescription>
                Only installed and compatible engines are listed.
              </SheetDescription>
            </SheetHeader>
            <div className="grid gap-2 pb-4">
              {enabledEngines.map((engine) => (
                <Button
                  key={engine.id}
                  type="button"
                  variant={engine.id === state.mode ? 'secondary' : 'outline'}
                  className="h-11 justify-start"
                  onClick={() => {
                    setMode(engine.id)
                    setSheetOpen(false)
                  }}
                  data-book-preview-press
                >
                  <span className="flex flex-col items-start">
                    <span>{engine.label}</span>
                    <span className="text-muted-foreground text-xs font-normal">
                      {engine.description}
                    </span>
                  </span>
                </Button>
              ))}
            </div>
          </SheetContent>
        </Sheet>
      </div>
      <div className="contents [@media(pointer:coarse)]:hidden">
        <ToggleGroup
          value={[state.mode]}
          onValueChange={(value) => {
            const next = value[0]
            if (next) setMode(next as BookPreviewMode)
          }}
          variant="outline"
          size="sm"
          spacing={0}
          aria-label="Reader mode"
          data-book-preview-modes
          className="flex max-w-full flex-wrap"
        >
          {enabledEngines.map((engine) => (
            <ToggleGroupItem
              key={engine.id}
              value={engine.id}
              aria-label={engine.label}
              onMouseEnter={() => {
                if (finePointer) prefetchMode(engine.id)
              }}
              onFocus={() => prefetchMode(engine.id)}
            >
              {engine.label}
            </ToggleGroupItem>
          ))}
        </ToggleGroup>
      </div>
    </>
  )
}

'use client'

import {
  IconAlertCircle,
  IconBook2,
  IconLoader2,
  IconShieldOff,
} from '@tabler/icons-react'
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert'
import { Button } from '@/components/ui/button'
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from '@/components/ui/empty'
import { Skeleton } from '@/components/ui/skeleton'
import { Spinner } from '@/components/ui/spinner'
import type { BookPreviewError, BookPreviewStatus } from './types'

type BookPreviewStatusProps = {
  status: BookPreviewStatus
  error: BookPreviewError | null
  onRetry?: () => void
  onReload?: () => void
  onFallback?: () => void
  fallbackLabel?: string
}

export function BookPreviewStatus({
  status,
  error,
  onRetry,
  onReload,
  onFallback,
  fallbackLabel = 'Open lightweight reader',
}: BookPreviewStatusProps) {
  if (status === 'loading' || status === 'idle') {
    return <LoadingStatus />
  }

  if (status === 'empty') {
    return <EmptyStatus />
  }

  if (status === 'unsupported') {
    return (
      <UnsupportedStatus
        message={error?.message}
        onFallback={onFallback}
        fallbackLabel={fallbackLabel}
      />
    )
  }

  if (status === 'error' && error) {
    return (
      <ErrorStatus
        error={error}
        onRetry={onRetry}
        onReload={onReload}
        onFallback={onFallback}
        fallbackLabel={fallbackLabel}
      />
    )
  }

  return null
}

function LoadingStatus() {
  return (
    <div
      className="flex h-full w-full flex-col items-center justify-center gap-4 p-6"
      role="status"
    >
      <Spinner />
      <div className="flex w-full max-w-sm flex-col gap-2">
        <Skeleton className="h-4 w-3/4" />
        <Skeleton className="h-4 w-1/2" />
      </div>
      <p className="text-muted-foreground text-sm">Loading reader…</p>
    </div>
  )
}

function EmptyStatus() {
  return (
    <Empty className="h-full border-dashed">
      <EmptyHeader>
        <EmptyMedia variant="icon">
          <IconBook2 />
        </EmptyMedia>
        <EmptyTitle>No book to preview</EmptyTitle>
        <EmptyDescription>
          Provide pages or a document source to render this reader.
        </EmptyDescription>
      </EmptyHeader>
    </Empty>
  )
}

function UnsupportedStatus({
  message,
  onFallback,
  fallbackLabel,
}: {
  message?: string
  onFallback?: () => void
  fallbackLabel: string
}) {
  return (
    <Empty className="h-full">
      <EmptyHeader>
        <EmptyMedia variant="icon">
          <IconShieldOff />
        </EmptyMedia>
        <EmptyTitle>This mode is unavailable</EmptyTitle>
        <EmptyDescription>
          {message ??
            'The selected reader is not supported in this browser or source.'}
        </EmptyDescription>
      </EmptyHeader>
      {onFallback ? (
        <EmptyContent>
          <Button type="button" onClick={onFallback} data-book-preview-press>
            {fallbackLabel}
          </Button>
        </EmptyContent>
      ) : null}
    </Empty>
  )
}

function ErrorStatus({
  error,
  onRetry,
  onReload,
  onFallback,
  fallbackLabel,
}: {
  error: BookPreviewError
  onRetry?: () => void
  onReload?: () => void
  onFallback?: () => void
  fallbackLabel: string
}) {
  return (
    <div className="flex h-full items-center justify-center p-6">
      <Alert variant="destructive" className="max-w-md">
        <IconAlertCircle />
        <AlertTitle>Unable to open this reader</AlertTitle>
        <AlertDescription>
          <p>{error.message}</p>
          <div className="mt-3 flex flex-wrap gap-2">
            {onReload && error.kind === 'engine-load' ? (
              <Button
                type="button"
                size="sm"
                onClick={onReload}
                data-book-preview-press
              >
                Reload page
              </Button>
            ) : null}
            {onRetry ? (
              <Button
                type="button"
                size="sm"
                variant="outline"
                onClick={onRetry}
                data-book-preview-press
              >
                <IconLoader2 data-icon="inline-start" />
                Retry
              </Button>
            ) : null}
            {onFallback ? (
              <Button
                type="button"
                size="sm"
                variant={onReload ? 'outline' : 'default'}
                onClick={onFallback}
                data-book-preview-press
              >
                {fallbackLabel}
              </Button>
            ) : null}
          </div>
        </AlertDescription>
      </Alert>
    </div>
  )
}

'use client'

import type { BookPreviewError, BookPreviewMode } from './types'
import { Component, type ErrorInfo, type ReactNode } from 'react'

type BookPreviewEngineBoundaryProps = {
  engineId: BookPreviewMode | string
  resetKey?: string
  onError: (error: BookPreviewError) => void
  children: ReactNode
}

type BookPreviewEngineBoundaryState = {
  failed: boolean
  prevEngineId: BookPreviewMode | string
  prevResetKey?: string
}

export class BookPreviewEngineBoundary extends Component<
  BookPreviewEngineBoundaryProps,
  BookPreviewEngineBoundaryState
> {
  state: BookPreviewEngineBoundaryState = {
    failed: false,
    prevEngineId: this.props.engineId,
    prevResetKey: this.props.resetKey,
  }

  static getDerivedStateFromError(): Partial<BookPreviewEngineBoundaryState> {
    return { failed: true }
  }

  // A new engine or source clears the failure during render — no
  // componentDidUpdate setState round-trip.
  static getDerivedStateFromProps(
    props: BookPreviewEngineBoundaryProps,
    state: BookPreviewEngineBoundaryState,
  ): Partial<BookPreviewEngineBoundaryState> | null {
    if (
      props.engineId === state.prevEngineId &&
      props.resetKey === state.prevResetKey
    ) {
      return null
    }
    return {
      failed: false,
      prevEngineId: props.engineId,
      prevResetKey: props.resetKey,
    }
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    this.props.onError({
      kind: 'page-render',
      message: 'This reader encountered an unexpected error.',
    })
    if (process.env.NODE_ENV !== 'production') {
      console.error(error, info.componentStack)
    }
  }

  render() {
    if (this.state.failed) return null
    return this.props.children
  }
}

'use client'

import type { ReactNode } from 'react'
import { Button } from '@/components/ui/button'
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/components/ui/tooltip'

type BookPreviewIconButtonProps = {
  label: string
  pressed?: boolean
  disabled?: boolean
  onClick?: () => void
  children: ReactNode
}

export function BookPreviewIconButton({
  label,
  pressed,
  disabled,
  onClick,
  children,
}: BookPreviewIconButtonProps) {
  const button = (
    <Button
      type="button"
      variant={pressed ? 'secondary' : 'ghost'}
      size="icon-sm"
      aria-label={label}
      aria-pressed={pressed}
      disabled={disabled}
      onClick={onClick}
      data-book-preview-press
      className="min-h-11 min-w-11 sm:min-h-7 sm:min-w-7"
    >
      {children}
    </Button>
  )

  if (disabled) {
    return (
      <Tooltip>
        <TooltipTrigger render={<span className="inline-flex" />}>
          {button}
        </TooltipTrigger>
        <TooltipContent>{label}</TooltipContent>
      </Tooltip>
    )
  }

  return (
    <Tooltip>
      <TooltipTrigger render={button} />
      <TooltipContent>{label}</TooltipContent>
    </Tooltip>
  )
}

import type { ComponentProps } from 'react'
import { cn } from '@/lib/utils'

/**
 * Animated audio bars shown while read-aloud is active — the affordance
 * ElevenLabs-style audio UIs use, adapted to SpeechSynthesis (which has no
 * media element to wire a real waveform/analyser to). Pure CSS, currentColor,
 * and frozen under prefers-reduced-motion.
 */
export function SpeakingBars({ className, ...props }: ComponentProps<'span'>) {
  return (
    <span
      {...props}
      aria-hidden
      className={cn('inline-flex items-end gap-[3px]', className)}
    >
      {[0, 1, 2].map((bar) => (
        <span
          key={bar}
          className="bp-speaking-bar inline-block w-[2px] rounded-full bg-current"
          style={{ animationDelay: `${bar * 140}ms` }}
        />
      ))}
    </span>
  )
}

